{
  "personality": {
    "traits": [
      "好胜",
      "直率",
      "护短"
    ],
    "values": [
      "部族荣誉",
      "勇武立身"
    ],
    "flaws": [
      "急躁易怒"
    ]
  },
  "voice": {
    "register": "粗犷直白，惯用短句与命令口吻",
    "accent": "赭牙谷山地口音，尾音重，齿擦音粗粝",
    "habits": [
      "说话时磨动下唇獠牙",
      "发怒前先哼一声"
    ],
    "samples": [
      "停战？那是没牙的老兽才说的话。",
      "碎岩部的人，骨头比石头硬。",
      "要谈，先赢过我手里的骨棒。"
    ]
  },
  "background": "生於赭牙谷碎岩部，自幼随部众狩猎、巡山，以敢冲敢打闻名。成年后接掌部中主战之责，成为主战的年轻部首，常率小队巡守谷口，拒外客于隘外。近岁部盟内停战之议渐起，他坚持旧例，认为退让只会招来更多窥伺。",
  "currentConcern": "部盟停战之议将定，他怕族人就此放下骨棒，任人宰割。",
  "goals": [
    "让碎岩部在部盟议事中保住主战之声",
    "守住赭牙谷隘口，不让外客随意深入"
  ],
  "fears": [
    "部族因停战而失去威慑，被外敌吞并"
  ],
  "knowledge": {
    "unknown": [
      "山外诸郡的农耕与市集如何运作",
      "停战派首领真正的顾虑与底牌"
    ]
  },
  "relationships": [],
  "visibleFeature": "左颊有一道从颧骨裂到嘴角的旧伤，断了一截右獠牙，颈上串着三枚磨圆的碎石。"
}
